:root {
  --bg-card: #0d2b3e;
  --bg-header: #0a2030;
  --bg-section: #112d42;
  --bg-footer: #0a2030;
  --bg-species: #143450;
  --accent-teal: #2ec4b6;
  --accent-blue: #4fc3f7;
  --text-primary: #e0f4ff;
  --text-secondary: #7db8d4;
  --text-muted: #4a7a96;
  --status-good: #56cfb2;
  --status-warn: #f4a261;
  --status-alert: #ff6b6b;
  --fill-coral: #2ec4b6;
  --fill-clarity: #4fc3f7;
  --fill-bleach: #ff6b6b;
  --border-subtle: #1e4a66;
  --badge-bg: #2ec4b6;
  --badge-text: #0d2b3e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.survey-log {
  background: var(--bg-card);
  border-radius: 12px;
  width: 476px;
  overflow: hidden;
  border: 1.5px solid var(--border-subtle);
}

.log-header {
  background: var(--bg-header);
  padding: 9px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1.5px solid var(--border-subtle);
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.log-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 1.5px;
  padding: 2px 7px;
  border-radius: 20px;
  align-self: flex-start;
}

.log-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.log-subtitle {
  font-size: 10px;
  color: var(--text-secondary);
}

.header-right {
  display: flex;
  gap: 8px;
}

.depth-gauge,
.temp-gauge {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--bg-section);
  border: 1px solid var(--border-subtle);
  border-radius: 7px;
  padding: 4px 10px;
  min-width: 48px;
}

.gauge-label {
  font-size: 8px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 1px;
}

.gauge-value {
  font-size: 14px;
  font-weight: 800;
  color: var(--accent-teal);
  line-height: 1.2;
}

.survey-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  padding: 8px 14px 6px;
}

.species-card {
  background: var(--bg-species);
  border-radius: 8px;
  padding: 6px 8px;
  display: flex;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--border-subtle);
}

.species-icon {
  font-size: 18px;
  line-height: 1;
  flex-shrink: 0;
}

.species-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-width: 0;
}

.species-name {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.species-status {
  font-size: 9px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 20px;
  align-self: flex-start;
}

.status-good {
  background: color-mix(in srgb, var(--status-good) 20%, transparent);
  color: var(--status-good);
}

.status-warn {
  background: color-mix(in srgb, var(--status-warn) 20%, transparent);
  color: var(--status-warn);
}

.status-alert {
  background: color-mix(in srgb, var(--status-alert) 20%, transparent);
  color: var(--status-alert);
}

.species-count {
  font-size: 16px;
  font-weight: 800;
  color: var(--accent-blue);
  flex-shrink: 0;
}

.health-bar-section {
  padding: 6px 14px 8px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  border-top: 1px solid var(--border-subtle);
}

.health-row {
  display: flex;
  align-items: center;
  gap: 7px;
}

.health-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-secondary);
  width: 82px;
  flex-shrink: 0;
}

.health-track {
  flex: 1;
  height: 6px;
  background: var(--bg-section);
  border-radius: 20px;
  overflow: hidden;
  border: 1px solid var(--border-subtle);
}

.health-fill {
  height: 100%;
  border-radius: 20px;
}

.fill-coral {
  width: 62%;
  background: var(--fill-coral);
}

.fill-clarity {
  width: 88%;
  background: var(--fill-clarity);
}

.fill-bleach {
  width: 34%;
  background: var(--fill-bleach);
}

.health-pct {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-primary);
  width: 28px;
  text-align: right;
  flex-shrink: 0;
}

.log-footer {
  background: var(--bg-footer);
  border-top: 1.5px solid var(--border-subtle);
  padding: 8px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.diver-info {
  display: flex;
  align-items: center;
  gap: 7px;
}

.diver-avatar {
  font-size: 18px;
  line-height: 1;
}

.diver-details {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.diver-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-primary);
}

.diver-cert {
  font-size: 9px;
  color: var(--text-muted);
}

.footer-meta {
  display: flex;
  align-items: center;
  gap: 5px;
}

.meta-tag {
  font-size: 9px;
  color: var(--text-secondary);
  background: var(--bg-section);
  border: 1px solid var(--border-subtle);
  border-radius: 20px;
  padding: 2px 6px;
}

.log-date {
  font-size: 10px;
  font-weight: 800;
  color: var(--accent-teal);
  letter-spacing: 0.5px;
}
